def esc(t):
    # Android XML: & and < must be entity-escaped. Apostrophe ' must be \' (we have none).
    t = t.replace('&', '&amp;').replace('<', '&lt;')
    return t

def fmt_unguarded(v):
    fmt = re.compile(r'%\d+\$[sd]|%[sd]|%%')
    return fmt.sub('', v).count('%')

