applied, skipped, updated = [], [], []

# 1) Replace existing string keys in-place; collect NEW ones for insert
to_insert = []
for key, val in S.items():
    assert fmt_unguarded(val) == 0, f"unguarded % in {key}"
    body = esc(val)
    line = f'    <string name="{key}">{body}</string>'
    pat = re.compile(r'[ \t]*<string name="' + re.escape(key) + r'">.*?</string>', re.DOTALL)
    if pat.search(content):
        content, n = pat.subn(line, content, count=1)
        updated.append(key)
        applied.append(key)
    else:
        to_insert.append(line)
        applied.append(key)

# 2) Replace plurals in-place (they are stale German -> all exist)
for key, forms in PL.items():
    for f_ in forms.values():
        assert fmt_unguarded(f_) == 0, f"unguarded % in plural {key}"
    items = '\n'.join(f'        <item quantity="{q}">{esc(t)}</item>' for q, t in forms.items())
    block = f'    <plurals name="{key}">\n{items}\n    </plurals>'
    pat = re.compile(r'[ \t]*<plurals name="' + re.escape(key) + r'">.*?</plurals>', re.DOTALL)
    if pat.search(content):
        content, n = pat.subn(block, content, count=1)
        updated.append(key)
        applied.append(key)
    else:
        to_insert.append(block)
        applied.append(key)

# 3) rfind-insert NEW entries before </resources>
if to_insert:
    idx = content.rfind('</resources>')
    if idx == -1:
        raise RuntimeError("kein </resources> gefunden — Datei korrupt")
    ins = '\n'.join(to_insert) + '\n'
    content = content[:idx] + ins + content[idx:]

if content != orig:
    with open(TARGET, 'w', encoding='utf-8', newline='\n') as f:
        f.write(content)

print(json.dumps({
    'updated_inplace': updated,
    'inserted_new': [l.split('name="')[1].split('"')[0] for l in to_insert],
    'applied_count': len(applied),
}, ensure_ascii=False, indent=1))
